"""
尺取り法 (Two Pointers / 2点ポインタ)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
単調性を利用して区間 [l, r) を走査し、条件を満たす区間数や最長区間を O(N) で数え上げる。

【代表パターン】
1. count_subarrays(a, k, check_fn): 条件を満たす連続部分列の総数をカウント
2. diff_pairs(a, k): ソート済み配列 a において a[j] - a[i] == k (j > i) を満たすペア数をカウント
   ※広義単調リストで差がKに一致する場合の数を出す。普通にやると戻りが発生するので右を2つ持つ。
"""

# https://github.com/ddfkit/acsampl/blob/main/shakutori.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def diff_pairs(a,k):
    n=len(a);r1=r2=res=0
    for l in range(n):
        r1=max(r1,l+1);r2=max(r2,l+1)
        while r1<n and a[r1]-a[l]<k:r1+=1
        while r2<n and a[r2]-a[l]<=k:r2+=1
        res+=r2-r1
    return res

# https://github.com/ddfkit/acsampl/blob/main/shakutori.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def count_at_most_sum(a,k):
    r=s=ans=0;n=len(a)
    for l in range(n):
        while r<n and s+a[r]<=k:s+=a[r];r+=1
        ans+=r-l
        if l==r:r+=1
        else:s-=a[l]
    return ans

if __name__ == "__main__":
    # 広義単調リストで尺取で差がKに一致する場合の数を出す。普通にやると戻りが発生するので右を2つ持つ
    assert diff_pairs([0, 0, 1, 1, 1], 1) == 6
    assert diff_pairs([0, 0, 0, 0, 0], 0) == 10

    # 和が 3 以下の連続部分列数: [1, 2, 1] -> [1], [2], [1], [1,2], [2,1] = 5個
    assert count_at_most_sum([1, 2, 1], 3) == 5
    print("shakutori.py: all tests passed!")
